import React from "react";
import VoteList from "./VoteList"
import InactiveVoteComponents from "./InactiveVoteComponents"
import VoteComposer from "./VoteComposer"

export default function VoteController( {alleFragen }) {

    const [VoteComposerActive, setVoteComposerActive] = React.useState(false)

    return <div> 

        <VoteList alleFragen = { alleFragen } />
        {
            (VoteComposerActive)? <VoteComposer/> :<InactiveVoteComponents/> //If VoteComposer Active (if ist das ?) VoteComposer else InactiveVoteComponents
        }
    </div>
}
